import{_ as t,o,c as d,ag as s}from"./chunks/framework.BZohXCq9.js";const h=JSON.parse('{"title":"Student Dashboard -> Booked Lessons (deep)","description":"","frontmatter":{},"headers":[],"relativePath":"modules/student-dashboard/booked-lessons.md","filePath":"modules/student-dashboard/booked-lessons.md"}'),n={name:"modules/student-dashboard/booked-lessons.md"};function i(a,e,l,r,c,u){return o(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="student-dashboard-booked-lessons-deep" tabindex="-1">Student Dashboard -&gt; Booked Lessons (deep) <a class="header-anchor" href="#student-dashboard-booked-lessons-deep" aria-label="Permalink to &quot;Student Dashboard -&gt; Booked Lessons (deep)&quot;">​</a></h1><p><strong>Module:</strong> <code>student-dashboard</code><br><strong>Feature:</strong> <code>booked-lessons</code><br><strong>Routes:</strong> <code>/student-dashboard/book</code>, <code>/student-dashboard/booking-details</code>, <code>/student-dashboard/complete-payment</code></p><p>This feature owns the student’s active booking lifecycle: viewing booked lessons, tab-based status filtering, resuming abandoned checkout, completing later T-48/3DS payments, viewing booking details, cancelling a lesson, and requesting a refund.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><ul><li>Show all student bookings grouped into practical dashboard tabs.</li><li>Expose payment state clearly (<code>paid</code>, <code>pending_payment</code>, <code>requires_action</code>, <code>payment_failed</code>, refunded/cancelled cases).</li><li>Let students resume checkout or complete Stripe-auth steps later.</li><li>Provide detail view, cancel actions, and refund-request entry points.</li></ul><h2 id="frontend-files" tabindex="-1">Frontend files <a class="header-anchor" href="#frontend-files" aria-label="Permalink to &quot;Frontend files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Integration</th></tr></thead><tbody><tr><td><code>Frontend/src/pages/private/student-dashboard/bookLesson.tsx</code></td><td>Main booked-lessons page</td><td>Loads student bookings, groups them into dashboard tabs, handles resume-checkout and delayed-payment CTAs.</td></tr><tr><td><code>Frontend/src/components/BookingList.tsx</code></td><td>Booking card/list renderer</td><td>Renders tabs, booking cards, payment status chips, action buttons, and summary labels.</td></tr><tr><td><code>Frontend/src/pages/private/student-dashboard/bookingDetails.tsx</code></td><td>Booking detail screen</td><td>Handles returned Stripe state, specific slot actions, cancel/refund UI, and detailed booking display.</td></tr><tr><td><code>Frontend/src/pages/private/student-dashboard/CompletePaymentPage.tsx</code></td><td>Stripe.js payment completion screen</td><td>Completes T-48/3DS later-payment flows using a client secret.</td></tr><tr><td><code>Frontend/src/components/StudentComponents/GetSlotDurationInHours.ts</code></td><td>Slot duration helper</td><td>Used to convert slots into duration/hour displays.</td></tr><tr><td><code>Frontend/src/components/InstructorComponent/common/BackButton.tsx</code></td><td>Shared navigation helper</td><td>Used on nested detail flows.</td></tr></tbody></table><h2 id="frontend-graphql" tabindex="-1">Frontend GraphQL <a class="header-anchor" href="#frontend-graphql" aria-label="Permalink to &quot;Frontend GraphQL&quot;">​</a></h2><h3 id="booking-creation-checkout-continuation" tabindex="-1">Booking creation / checkout continuation <a class="header-anchor" href="#booking-creation-checkout-continuation" aria-label="Permalink to &quot;Booking creation / checkout continuation&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/studentBooking.ts</code></li><li>Relevant operations: <ul><li><code>CREATE_BOOKING_CHECKOUT_SESSION</code></li><li><code>CREATE_CHECKOUT_SESSION_FOR_PENDING_BOOKING</code></li><li><code>COMPLETE_BOOKING_FROM_CHECKOUT</code></li><li><code>COMPLETE_DEFERRED_BOOKING_FROM_CHECKOUT</code></li><li><code>COMPLETE_BOOKING_AFTER_PAYMENT</code></li></ul></li><li>Used by: <ul><li>booking creation return paths</li><li>abandoned checkout resumption</li><li>Stripe redirect return handling</li></ul></li></ul><h3 id="booked-lessons-listing-and-payment-completion" tabindex="-1">Booked lessons listing and payment completion <a class="header-anchor" href="#booked-lessons-listing-and-payment-completion" aria-label="Permalink to &quot;Booked lessons listing and payment completion&quot;">​</a></h3><ul><li>File: <code>Frontend/src/graphql/mutations/studentBooking.ts</code></li><li>Relevant operations: <ul><li><code>GET_STUDENT_BOOKINGS</code></li><li><code>GET_T48_CLIENT_SECRET</code></li><li><code>COMPLETE_T48_SLOT_PAYMENT</code></li><li><code>CANCEL_BOOKING</code></li></ul></li><li>Used by: <ul><li><code>bookLesson.tsx</code></li><li><code>bookingDetails.tsx</code></li><li><code>CompletePaymentPage.tsx</code></li></ul></li></ul><h3 id="refund-entry-points" tabindex="-1">Refund entry points <a class="header-anchor" href="#refund-entry-points" aria-label="Permalink to &quot;Refund entry points&quot;">​</a></h3><ul><li>Files: <ul><li><code>Frontend/src/graphql/mutations/studentBooking.ts</code></li><li><code>Frontend/src/graphql/mutations/refundRequest.ts</code></li></ul></li><li>Relevant operations: <ul><li><code>REQUEST_REFUND</code></li><li><code>GET_MY_REFUND_REQUESTS</code></li></ul></li><li>Used by: <ul><li>booked lesson actions</li><li>booking detail and payment/refund visibility states</li></ul></li></ul><h2 id="backend-schema" tabindex="-1">Backend schema <a class="header-anchor" href="#backend-schema" aria-label="Permalink to &quot;Backend schema&quot;">​</a></h2><h3 id="typedefs" tabindex="-1">TypeDefs <a class="header-anchor" href="#typedefs" aria-label="Permalink to &quot;TypeDefs&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/typeDefs/studentBooking.typeDefs.js</code></li><li>Relevant query/mutation fields: <ul><li><code>getStudentBookings</code></li><li><code>createBooking</code></li><li><code>createBookingCheckoutSession</code></li><li><code>createCheckoutSessionForPendingBooking</code></li><li><code>completeBookingFromCheckout</code></li><li><code>completeDeferredBookingFromCheckout</code></li><li><code>completeBookingAfterPayment</code></li><li><code>getT48ClientSecret</code></li><li><code>completeT48SlotPayment</code></li><li><code>cancelBookingSlot</code></li><li><code>updateSlotStatus</code></li></ul></li><li>File: <code>server/src/graphql/typeDefs/refundRequest.typeDefs.js</code><ul><li><code>requestRefund</code></li><li><code>getMyRefundRequests</code></li></ul></li></ul><h3 id="resolvers" tabindex="-1">Resolvers <a class="header-anchor" href="#resolvers" aria-label="Permalink to &quot;Resolvers&quot;">​</a></h3><ul><li>File: <code>server/src/graphql/resolvers/studentBooking.resolver.js</code></li><li>Key responsibilities: <ul><li>build booking documents and reserve availability</li><li>choose instant vs deferred checkout</li><li>store slot-level payment state (<code>paymentStatus</code>, <code>chargeAmount</code>, <code>dspCommission</code>, <code>instructorAmount</code>)</li><li>complete Stripe return flows</li><li>create/confirm T-48 later-payment flows</li><li>cancel booking slots with rule checks</li></ul></li><li>File: <code>server/src/graphql/resolvers/refundRequest.resolver.js</code><ul><li><code>Mutation.requestRefund</code><ul><li>Creates a refund request for a cancelled, unpaid-out slot.</li></ul></li></ul></li></ul><h2 id="main-backend-dependencies" tabindex="-1">Main backend dependencies <a class="header-anchor" href="#main-backend-dependencies" aria-label="Permalink to &quot;Main backend dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>server/src/models/studentBooking.model.js</code></td><td>Primary booking and slot state store</td></tr><tr><td><code>server/src/models/teacherAvailability.model.js</code></td><td>Source of availability reservation/release sync</td></tr><tr><td><code>server/src/models/teacherTariff.model.js</code></td><td>Price/package input to booking amount calculation</td></tr><tr><td><code>server/src/models/refundRequest.model.js</code></td><td>Refund request queue state</td></tr><tr><td><code>server/src/services/stripeService.js</code></td><td>Checkout sessions, payment intents, T-48 payment completion, refund helpers</td></tr><tr><td><code>server/src/services/transactionService.js</code></td><td>Creates financial transaction rows tied to bookings</td></tr><tr><td><code>server/src/jobs/pendingBookingCleanupJob.js</code></td><td>Cleans abandoned pending bookings</td></tr><tr><td><code>server/src/jobs/t48ChargeJob.js</code></td><td>Charges deferred bookings at T-48</td></tr><tr><td><code>server/src/jobs/payoutJob.js</code></td><td>Pays instructors after completed paid lessons</td></tr><tr><td><code>server/src/routes/stripeWebhook.routes.js</code></td><td>Handles Stripe event-driven booking/payment transitions</td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>Student opens <code>/student-dashboard/book</code>.</li><li><code>GET_STUDENT_BOOKINGS</code> returns bookings with slot-level payment and status data.</li><li>UI groups bookings into: <ul><li>upcoming / active</li><li>abandoned checkout</li><li>cancelled</li><li>refund</li><li>completed-like surfaces</li></ul></li><li>If a booking is abandoned, the student can call <code>createCheckoutSessionForPendingBooking</code> to resume checkout.</li><li>If a T-48 payment required authentication, the student is routed to <code>CompletePaymentPage</code>: <ul><li>request client secret</li><li>complete Stripe confirmation</li><li>call <code>completeT48SlotPayment</code></li></ul></li><li>If a booking/slot is cancelled, <code>requestRefund</code> can create a pending refund request when refund rules are satisfied.</li><li>Backend keeps booking slots, availability slots, payment status, refund state, and transaction ledger in sync.</li></ol><h2 id="developer-notes" tabindex="-1">Developer notes <a class="header-anchor" href="#developer-notes" aria-label="Permalink to &quot;Developer notes&quot;">​</a></h2><ul><li>This module owns the most complex student-side business rules.</li><li>Slot-level fields (<code>paymentStatus</code>, <code>dspCommission</code>, <code>instructorAmount</code>, <code>refundAmount</code>, <code>payoutStatus</code>) are critical; many downstream flows depend on them instead of recalculating history later.</li><li>Booking details and complete-payment routes are functionally part of this module, even though they are separate route files.</li></ul>',25)])])}const m=t(n,[["render",i]]);export{h as __pageData,m as default};
